/** Подписи рисунков: заменяем текстовые поля (s) по словарю, остальное не меняем. */
const tf = (f: Figure | Figure[], m: Record<string, string>): Figure | Figure[] => {
  const one = (g: Figure): Figure => {
    if (g.kind !== "scene") return g;
    return { ...g, items: g.items.map((it) => (it.t === "text" && typeof it.s === "string" && m[it.s] ? { ...it, s: m[it.s] } : it)) };
  };
  return Array.isArray(f) ? f.map(one) : one(f);
};
